// The drums a print uses. On the page they are CSS variables, so an ink set (data-inks) or the theme re-inks every
// print without re-rendering it; share images render without a stylesheet and pass plain colours instead.

export interface PrintInks {
  /** The line drum: structure. */
  line: string
  /** The accent drum: the point of interest. */
  accent: string
  /** A small dark detail. */
  detail: string
  /** Letters a motif prints, such as a monogram; falls back to the detail drum. */
  text?: string
}

export const CSS_INKS: PrintInks = {
  line: "var(--print-line)",
  accent: "var(--print-accent)",
  detail: "var(--print-detail)",
  text: "var(--ink)",
}

/** Named ink sets, defined in styles/inks.css. */
export const INK_SETS = ["patina", "field", "fluoro", "earth", "spot"] as const
export type InkSet = (typeof INK_SETS)[number]

// Letterpress offcuts stacked and slightly tumbling; one block inked, a type sort fallen beside them.
import { sketch } from "../rough"
import { stream } from "../seed"
import { pens, seeds, turn, type Point } from "./pens"
import type { Motif } from "./types"

function box(
  cx: number,
  cy: number,
  w: number,
  h: number,
  angle: number,
): Point[] {
  const corners: Point[] = [
    [cx - w / 2, cy - h / 2],
    [cx + w / 2, cy - h / 2],
    [cx + w / 2, cy + h / 2],
    [cx - w / 2, cy + h / 2],
  ]
  return corners.map((p) => turn(p, [cx, cy], angle))
}

export const blocks: Motif = (seed, inks) => {
  const place = stream(seed, "blocks:place")
  const s = seeds(seed, "blocks")
  const pen = pens(inks)
  const inked = 1 + Math.floor(place.next() * 3)
  let floor = 222
  const stack = Array.from({ length: 5 }, (_, i) => {
    const w = place.between(60, 118) * (1 - i * 0.08)
    const h = place.between(24, 36)
    const cx = 120 + place.between(-16, 16)
    const cy = floor - h / 2
    floor -= h - 1
    return box(cx, cy, w, h, place.between(-0.06, 0.06) * (1 + i))
  })
  const sort = box(place.between(28, 52), 214, 16, 20, place.between(0.2, 0.5))
  const solid = {
    stroke: inks.detail,
    fill: inks.detail,
    fillStyle: "solid" as const,
    strokeWidth: 1,
    roughness: 0.6,
  }
  const hatch = {
    fill: inks.accent,
    fillStyle: "hachure" as const,
    hachureGap: 5,
    hachureAngle: -35,
  }

  return {
    line: stack
      .map((b, i) =>
        i === inked
          ? ""
          : sketch.polygon(b, {
              ...pen.fine,
              strokeWidth: 2.6,
              seed: s(`block-${i}`),
            }),
      )
      .join(""),
    detail: sketch.polygon(sort, { ...solid, seed: s("sort") }),
    accent: sketch.polygon(stack[inked] ?? [], {
      ...pen.accent,
      strokeWidth: 2.6,
      ...hatch,
      seed: s("inked"),
    }),
  }
}

// Cut paper: three to five shapes (torn slabs, half discs, triangles, strips, a dot) in solid ink, scattered and
// overlapping so the drums overprint. The seed picks the shapes, their order, places and turns.
import { sketch } from "../rough"
import { stream } from "../seed"
import { seeds, turn, type Point } from "./pens"
import type { Motif } from "./types"

type Place = ReturnType<typeof stream>
type Shape = (p: Place, c: Point, size: number) => Point[]

const around = (points: Point[], centre: Point, angle: number) =>
  points.map((p) => turn(p, centre, angle))

/** A rectangle with one torn edge. */
const slab: Shape = (p, [cx, cy], size) => {
  const w = size * p.between(1.1, 1.6)
  const h = size * p.between(0.6, 0.9)
  const top: Point[] = Array.from({ length: 9 }, (_, i) => [
    cx - w / 2 + (w * i) / 8,
    cy - h / 2 + p.between(-5, 5),
  ])
  return around(
    [...top, [cx + w / 2, cy + h / 2], [cx - w / 2, cy + h / 2]],
    [cx, cy],
    p.between(-0.4, 0.4),
  )
}

/** A half disc. */
const half: Shape = (p, [cx, cy], size) => {
  const r = size * p.between(0.45, 0.6)
  const arc: Point[] = Array.from({ length: 13 }, (_, i) => {
    const a = Math.PI + (i / 12) * Math.PI
    return [cx + Math.cos(a) * r, cy + Math.sin(a) * r]
  })
  return around(arc, [cx, cy], p.between(0, 6.28))
}

/** A triangle. */
const triangle: Shape = (p, [cx, cy], size) => {
  const s = size * p.between(0.4, 0.55)
  return around(
    [
      [cx, cy - s],
      [cx + s * 0.9, cy + s * 0.55],
      [cx - s * 0.8, cy + s * 0.5],
    ],
    [cx, cy],
    p.between(0, 6.28),
  )
}

/** A long strip, like a cut-off edge of a sheet. */
const strip: Shape = (p, [cx, cy], size) => {
  const w = size * p.between(1.4, 2)
  const h = size * p.between(0.14, 0.22)
  return around(
    [
      [cx - w / 2, cy - h / 2],
      [cx + w / 2, cy - h / 2 + p.between(-3, 3)],
      [cx + w / 2, cy + h / 2],
      [cx - w / 2, cy + h / 2],
    ],
    [cx, cy],
    p.between(-0.9, 0.9),
  )
}

const SHAPES = [slab, half, triangle, strip]

export const collage: Motif = (seed, inks) => {
  const place = stream(seed, "collage:place")
  const s = seeds(seed, "collage")
  const out = { line: "", accent: "", detail: "" }
  const solid = (color: string, label: string) => ({
    seed: s(label),
    stroke: color,
    fill: color,
    fillStyle: "solid" as const,
    strokeWidth: 1,
    roughness: 0.7,
  })
  const count = 3 + Math.floor(place.next() * 3)

  for (let i = 0; i < count; i++) {
    const shape = place.pick(SHAPES)
    const centre: Point = [place.between(88, 152), place.between(88, 152)]
    const size = place.between(60, 92) * (i === 0 ? 1.15 : 1)
    // The first and largest shape prints in the line drum; the rest alternate drums.
    const drum = i === 0 ? "line" : place.next() > 0.35 ? "accent" : "line"
    out[drum] += sketch.polygon(
      shape(place, centre, size),
      solid(inks[drum], `shape-${i}`),
    )
  }
  const dot: Point = [place.between(40, 200), place.between(40, 200)]
  out.detail += sketch.circle(
    dot[0],
    dot[1],
    place.between(16, 28),
    solid(inks.detail, "dot"),
  )
  return out
}

// A small constellation of linked ideas, one of them ringed. From Mental Models' riso drawing for concepts.
import { sketch } from "../rough"
import { stream } from "../seed"
import { dot, pens, seeds, type Point } from "./pens"
import type { Motif } from "./types"

export const constellation: Motif = (seed, inks) => {
  const place = stream(seed, "constellation:place")
  const s = seeds(seed, "constellation")
  const pen = pens(inks)
  const stars: Point[] = Array.from({ length: 6 }, (_, i) => {
    const angle = (i / 6) * Math.PI * 2 + place.between(-0.3, 0.3)
    const radius = i === 0 ? 0 : place.between(55, 92)
    return [120 + Math.cos(angle) * radius, 120 + Math.sin(angle) * radius]
  })
  const [hub, ...rest] = stars as [Point, ...Point[]]
  const link = (a: Point, b: Point, label: string) =>
    sketch.line(a[0], a[1], b[0], b[1], { ...pen.fine, seed: s(label) })
  const target = stars[2 + Math.floor(place.next() * 3)] ?? hub

  return {
    line:
      rest.map((star, i) => link(hub, star, `spoke-${i}`)).join("") +
      link(stars[1] ?? hub, stars[2] ?? hub, "chord-a") +
      link(stars[3] ?? hub, stars[4] ?? hub, "chord-b"),
    detail: stars
      .map(([x, y], i) =>
        dot(x, y, i === 0 ? 24 : 13, inks.detail, s(`star-${i}`)),
      )
      .join(""),
    accent:
      sketch.circle(target[0], target[1], 46, {
        ...pen.accent,
        seed: s("ring"),
      }) + dot(target[0] + 2.5, target[1] - 2, 14, inks.accent, s("ring-ink")),
  }
}

// Topographic lines round a peak and a smaller hill, with a dashed route up in the accent drum.
import { sketch } from "../rough"
import { stream } from "../seed"
import { blob, dot, pens, seeds, type Point } from "./pens"
import type { Motif } from "./types"

export const contours: Motif = (seed, inks) => {
  const place = stream(seed, "contours:place")
  const s = seeds(seed, "contours")
  const pen = pens(inks)
  const peak: Point = [place.between(105, 140), place.between(100, 130)]
  const phase: [number, number] = [
    place.between(0, 6.28),
    place.between(0, 6.28),
  ]
  const drift: Point = [place.between(-2.5, 2.5), place.between(-2.5, 2.5)]
  const away = place.between(0, 6.28)
  const hill: Point = [
    peak[0] + Math.cos(away) * 92,
    peak[1] + Math.sin(away) * 80,
  ]

  const levels = [20, 40, 61, 83, 106].map((r, k) =>
    sketch.loop(
      blob(
        peak[0] + drift[0] * k,
        peak[1] + drift[1] * k,
        r,
        0.1 + k * 0.025,
        phase,
        16,
      ),
      {
        ...pen.fine,
        strokeWidth: k === 4 ? 3.2 : 2.2,
        seed: s(`level-${k}`),
      },
    ),
  )
  const hills = [14, 30].map((r, k) =>
    sketch.loop(blob(hill[0], hill[1], r, 0.14, [phase[1], phase[0]], 12), {
      ...pen.fine,
      seed: s(`hill-${k}`),
    }),
  )
  const start: Point = [
    peak[0] + Math.cos(away + 2.6) * 125,
    peak[1] + Math.sin(away + 2.6) * 115,
  ]
  const bend: Point = [
    (start[0] + peak[0]) / 2 + place.between(-25, 25),
    (start[1] + peak[1]) / 2 + place.between(-25, 25),
  ]

  return {
    line: levels.join("") + hills.join(""),
    detail: dot(peak[0], peak[1], 13, inks.detail, s("summit")),
    accent:
      sketch.curve([start, bend, [peak[0] + 9, peak[1] + 7]], {
        ...pen.accent,
        strokeWidth: 3,
        strokeLineDash: [9, 8],
        seed: s("route"),
      }) + dot(start[0], start[1], 16, inks.accent, s("trailhead")),
  }
}

// Streamlines through a seeded noise field; a few of them print in the accent drum.
import { valueNoise } from "../noise"
import { sketch } from "../rough"
import { fork, stream } from "../seed"
import { dot, pens, seeds, type Point } from "./pens"
import type { Motif } from "./types"

export const flow: Motif = (seed, inks) => {
  const place = stream(seed, "flow:place")
  const s = seeds(seed, "flow")
  const pen = pens(inks)
  const field = valueNoise(fork(seed, "flow:field"), 80)
  const base = place.between(0, 6.28)
  const direction = (x: number, y: number) => base + (field(x, y) - 0.5) * 4.4

  const lines: Point[][] = []
  for (let row = 0; row < 4; row++)
    for (let col = 0; col < 4; col++) {
      let p: Point = [
        28 + col * 61 + place.between(-14, 14),
        28 + row * 61 + place.between(-14, 14),
      ]
      const path: Point[] = [p]
      for (let step = 0; step < 18; step++) {
        const a = direction(p[0], p[1])
        p = [p[0] + Math.cos(a) * 7, p[1] + Math.sin(a) * 7]
        if (p[0] < -12 || p[0] > 252 || p[1] < -12 || p[1] > 252) break
        path.push(p)
      }
      if (path.length > 4) lines.push(path)
    }
  const accented = new Set([
    Math.floor(place.next() * lines.length),
    Math.floor(place.next() * lines.length),
  ])

  return {
    line: lines
      .map((path, i) =>
        accented.has(i)
          ? ""
          : sketch.curve(path, { ...pen.fine, seed: s(`line-${i}`) }),
      )
      .join(""),
    detail: [...accented]
      .map((i) =>
        dot(
          lines[i]?.[0]?.[0] ?? 0,
          lines[i]?.[0]?.[1] ?? 0,
          11,
          inks.detail,
          s(`start-${i}`),
        ),
      )
      .join(""),
    accent: [...accented]
      .map((i) =>
        sketch.curve(lines[i] ?? [], {
          ...pen.accent,
          strokeWidth: 3.2,
          seed: s(`accent-${i}`),
        }),
      )
      .join(""),
  }
}

// A halftone field shaped like a seeded blob, with a second screen at another angle printing into moiré.
import { stream } from "../seed"
import { dot, seeds, turn, type Point } from "./pens"
import type { Motif } from "./types"

const r1 = (n: number) => Math.round(n * 10) / 10

function screen(
  centre: Point,
  reach: number,
  pitch: number,
  angle: number,
  size: number,
  color: string,
) {
  const out: string[] = []
  for (let y = -130; y <= 130; y += pitch)
    for (let x = -130; x <= 130; x += pitch) {
      const [px, py] = turn([centre[0] + x, centre[1] + y], centre, angle)
      const t = 1 - Math.hypot(px - centre[0], py - centre[1]) / reach
      if (t <= 0.04) continue
      out.push(
        `<circle cx="${r1(px)}" cy="${r1(py)}" r="${r1(size * t * (1.2 - 0.2 * t))}" style="fill:${color}"/>`,
      )
    }
  return out.join("")
}

export const halftone: Motif = (seed, inks) => {
  const place = stream(seed, "halftone:place")
  const s = seeds(seed, "halftone")
  const centre: Point = [place.between(100, 140), place.between(100, 140)]
  const a = place.between(0, 6.28)
  const offset = place.between(32, 48)
  const second: Point = [
    centre[0] + Math.cos(a) * offset,
    centre[1] + Math.sin(a) * offset,
  ]

  return {
    line: screen(
      centre,
      place.between(106, 118),
      11,
      place.between(-0.2, 0.2),
      5.8,
      inks.line,
    ),
    detail: dot(second[0], second[1], 12, inks.detail, s("eye")),
    accent: screen(
      second,
      place.between(62, 74),
      10,
      place.between(0.35, 0.6),
      5.2,
      inks.accent,
    ),
  }
}

// A disc over wavy horizon bands, with glints on the water and two birds.
import { sketch } from "../rough"
import { stream } from "../seed"
import { dot, pens, seeds, type Point } from "./pens"
import type { Motif } from "./types"

export const horizon: Motif = (seed, inks) => {
  const place = stream(seed, "horizon:place")
  const s = seeds(seed, "horizon")
  const pen = pens(inks)
  const sun: Point = [place.between(70, 170), place.between(68, 100)]
  const radius = place.between(32, 44)
  const top = sun[1] + radius + place.between(8, 20)

  const bands = Array.from({ length: 4 }, (_, k) => {
    const y = top + k * place.between(17, 22)
    const amplitude = place.between(2.5, 6)
    const phase = place.between(0, 6.28)
    const points: Point[] = Array.from({ length: 9 }, (_, i) => [
      -8 + i * 32,
      y + Math.sin(i * 0.9 + phase) * amplitude,
    ])
    return sketch.curve(points, {
      ...(k === 0 ? pen.line : pen.fine),
      seed: s(`band-${k}`),
    })
  })
  const glints = [0, 1, 2].map((k) => {
    const y = top + 9 + k * 19
    const half = 22 - k * 6
    return sketch.line(
      sun[0] - half,
      y,
      sun[0] + half,
      y + place.between(-1.5, 1.5),
      { ...pen.accent, strokeWidth: 2.6, seed: s(`glint-${k}`) },
    )
  })
  const bird = (x: number, y: number, w: number, label: string) =>
    sketch.curve(
      [
        [x - w, y - w * 0.4],
        [x, y],
        [x + w, y - w * 0.45],
      ],
      { stroke: inks.detail, strokeWidth: 2.2, roughness: 0.8, seed: s(label) },
    )
  const flock: Point = [place.between(40, 200), place.between(22, 48)]

  return {
    line: bands.join(""),
    detail:
      bird(flock[0], flock[1], 9, "bird-a") +
      bird(flock[0] + 22, flock[1] + 9, 7, "bird-b"),
    accent:
      dot(sun[0], sun[1], radius * 2, inks.accent, s("sun")) + glints.join(""),
  }
}

// A lens on crosshair guides, its accent hatched. From Mental Models' riso drawing for tools.
import { sketch } from "../rough"
import { stream } from "../seed"
import { dot, pens, seeds } from "./pens"
import type { Motif } from "./types"

export const lens: Motif = (seed, inks) => {
  const place = stream(seed, "lens:place")
  const s = seeds(seed, "lens")
  const pen = pens(inks)
  const cx = place.between(100, 140)
  const cy = place.between(100, 135)
  const ax = cx + place.between(20, 40)
  const ay = cy - place.between(20, 40)

  return {
    line:
      sketch.circle(cx, cy, 150, { ...pen.line, seed: s("lens") }) +
      sketch.line(cx - 110, cy, cx + 110, cy + place.between(-6, 6), {
        ...pen.fine,
        strokeWidth: 2,
        seed: s("horizontal"),
      }) +
      sketch.line(cx, cy - 110, cx + place.between(-6, 6), cy + 110, {
        ...pen.fine,
        strokeWidth: 2,
        seed: s("vertical"),
      }),
    detail: dot(ax - 1, ay + 1.5, 16, inks.detail, s("focus")),
    accent: sketch.circle(ax, ay, 58, {
      ...pen.accent,
      seed: s("glint"),
      fill: inks.accent,
      fillStyle: "hachure",
      hachureGap: 5,
      fillWeight: 2.2,
      hachureAngle: -40,
    }),
  }
}

// Linocut: bold parallel gouges that swell and taper like carved water, a solid form cut into them, a few chips.
import { sketch } from "../rough"
import { stream } from "../seed"
import { blob, seeds, type Point } from "./pens"
import type { Motif } from "./types"

export const lino: Motif = (seed, inks) => {
  const place = stream(seed, "lino:place")
  const s = seeds(seed, "lino")
  const swell = place.between(5, 11)
  const phase = place.between(0, 6.28)
  const form: Point = [place.between(80, 160), place.between(70, 120)]
  const radius = place.between(34, 48)

  // Gouges stop where they meet the form, as if carved around it.
  const gouges: string[] = []
  for (let k = 0; k < 9; k++) {
    const y0 = 40 + k * 20
    const points: Point[] = Array.from({ length: 13 }, (_, i) => [
      i * 20,
      y0 + Math.sin(i * 0.7 + phase + k * 0.35) * swell,
    ])
    let run: Point[] = []
    const flush = () => {
      if (run.length > 1)
        gouges.push(
          sketch.curve(run, {
            seed: s(`gouge-${k}-${gouges.length}`),
            stroke: inks.line,
            strokeWidth: 3 + ((k * 7) % 4),
            roughness: 0.6,
          }),
        )
      run = []
    }
    for (const p of points) {
      if (Math.hypot(p[0] - form[0], p[1] - form[1]) < radius + 10) flush()
      else run.push(p)
    }
    flush()
  }
  const chips = Array.from({ length: 5 }, (_, i) =>
    sketch.circle(
      place.between(20, 220),
      place.between(30, 220),
      place.between(4, 8),
      {
        seed: s(`chip-${i}`),
        stroke: inks.detail,
        fill: inks.detail,
        fillStyle: "solid",
        strokeWidth: 1,
        roughness: 0.6,
      },
    ),
  )

  return {
    line: gouges.join(""),
    accent: sketch.polygon(
      blob(form[0], form[1], radius, 0.08, [phase, phase * 2], 18),
      {
        seed: s("form"),
        stroke: inks.accent,
        fill: inks.accent,
        fillStyle: "solid",
        strokeWidth: 1,
        roughness: 0.7,
      },
    ),
    detail: chips.join(""),
  }
}

// Initials printed over a seeded blob inside a drawn ring, for avatars, workspaces and marks.
import { sketch } from "../rough"
import { stream } from "../seed"
import { blob, pens, seeds } from "./pens"
import type { Motif } from "./types"

/** Up to two initials from a name: "Ossian Ravn" gives "OR", "patina" gives "P". */
export function initials(text = "") {
  const words = text.trim().split(/\s+/).filter(Boolean)
  const letters = words.length > 1 ? [words[0], words[words.length - 1]] : words
  return letters.map((w) => [...(w ?? "")][0]?.toUpperCase() ?? "").join("")
}

const escape = (text: string) =>
  text.replace(/[&<>"]/g, (c) => `&#${c.charCodeAt(0)};`)

export const monogram: Motif = (seed, inks, { text }) => {
  const place = stream(seed, "monogram:place")
  const s = seeds(seed, "monogram")
  const pen = pens(inks)
  const phase: [number, number] = [
    place.between(0, 6.28),
    place.between(0, 6.28),
  ]
  const shape = blob(
    120 + place.between(-6, 6),
    120 + place.between(-6, 6),
    74,
    0.09,
    phase,
    16,
  )
  const letters = initials(text)
  const size = letters.length > 1 ? 84 : 104
  const type = `fill:${inks.text ?? inks.detail};font-family:var(--face-read, Georgia, serif);font-size:${size}px;font-weight:650;letter-spacing:-0.02em`

  return {
    line: sketch.circle(
      120 + place.between(-4, 4),
      120 + place.between(-4, 4),
      196,
      { ...pen.fine, strokeWidth: 3, seed: s("ring") },
    ),
    accent: sketch.polygon(shape, {
      seed: s("blob"),
      stroke: inks.accent,
      fill: inks.accent,
      fillStyle: "solid",
      strokeWidth: 1.5,
      roughness: 0.8,
    }),
    detail: letters
      ? `<text x="120" y="122" text-anchor="middle" dominant-baseline="central" style="${type}">${escape(letters)}</text>`
      : "",
  }
}

// Two orbits; an accent body drifts round the outer one. From Mental Models' riso drawing for patterns.
import { sketch } from "../rough"
import { stream } from "../seed"
import { dot, pens, seeds } from "./pens"
import type { Motif } from "./types"

export const orbits: Motif = (seed, inks) => {
  const place = stream(seed, "orbits:place")
  const s = seeds(seed, "orbits")
  const pen = pens(inks)
  const cx = place.between(138, 152)
  const cy = place.between(98, 112)
  const outer = { x: cx - 8, y: cy + 10 }
  const angle = place.between(2.2, 2.7)
  const body = {
    x: outer.x + Math.cos(angle) * 113,
    y: outer.y + Math.sin(angle) * 113,
  }

  return {
    line:
      sketch.circle(cx, cy, 150, { ...pen.line, seed: s("inner") }) +
      sketch.circle(outer.x, outer.y, 226, { ...pen.line, seed: s("outer") }),
    detail: dot(cx, cy, 19, inks.detail, s("core")),
    accent:
      dot(cx + 2, cy - 1, 20, inks.accent, s("core-ink")) +
      sketch.circle(body.x, body.y, 54, {
        ...pen.accent,
        seed: s("body-ring"),
      }) +
      dot(body.x, body.y, 20, inks.accent, s("body")),
    pivot: outer,
  }
}

// Shared pens for motifs, so every print draws with the same weights as Mental Models' riso illustrations.
import type { PrintInks } from "../inks"
import { sketch } from "../rough"
import { fork } from "../seed"

export type Point = [number, number]

export function pens(inks: PrintInks) {
  return {
    /** Structure in the line drum. */
    line: { stroke: inks.line, strokeWidth: 4.2, roughness: 0.9 },
    /** Secondary structure in the line drum. */
    fine: { stroke: inks.line, strokeWidth: 2.2, roughness: 0.9 },
    /** The point of interest in the accent drum. */
    accent: { stroke: inks.accent, strokeWidth: 3.8, roughness: 0.9 },
  }
}

/** A filled, slightly rough dot. */
export function dot(
  x: number,
  y: number,
  d: number,
  color: string,
  seed: number,
) {
  return sketch.circle(x, y, d, {
    seed,
    stroke: color,
    fill: color,
    fillStyle: "solid",
    strokeWidth: 1,
    roughness: 0.6,
  })
}

/** Seeds for each drawn element, forked by motif and label so adding an element never shifts the others. */
export const seeds =
  (seed: number, motif: string) => (label: string | number) =>
    fork(seed, `${motif}:${label}`)

/** Points around an irregular closed shape: radius modulated by two seeded waves. */
export function blob(
  cx: number,
  cy: number,
  r: number,
  wobble: number,
  phase: [number, number],
  count = 14,
): Point[] {
  return Array.from({ length: count }, (_, i) => {
    const a = (i / count) * Math.PI * 2
    const k =
      1 +
      wobble *
        (Math.sin(a * 3 + phase[0]) * 0.6 + Math.sin(a * 5 + phase[1]) * 0.4)
    return [cx + Math.cos(a) * r * k, cy + Math.sin(a) * r * k]
  })
}

/** Rotates a point around a centre. */
export function turn([x, y]: Point, [cx, cy]: Point, angle: number): Point {
  const c = Math.cos(angle)
  const s = Math.sin(angle)
  return [cx + (x - cx) * c - (y - cy) * s, cy + (x - cx) * s + (y - cy) * c]
}

// Rings narrowing towards a pit. From Mental Models' riso drawing for traps.
import { sketch } from "../rough"
import { stream } from "../seed"
import { dot, pens, seeds } from "./pens"
import type { Motif } from "./types"

export const rings: Motif = (seed, inks) => {
  const place = stream(seed, "rings:place")
  const s = seeds(seed, "rings")
  const pen = pens(inks)
  const cx = place.between(105, 135)
  const cy = place.between(110, 130)
  const dx = place.between(-6, 6)
  const dy = place.between(4, 9)
  const pit = { x: cx + dx * 4.4, y: cy + dy * 4.4 }

  return {
    line: [190, 132, 80]
      .map((d, i) =>
        sketch.circle(cx + dx * i * 1.4, cy + dy * i * 1.4, d, {
          ...pen.line,
          seed: s(`ring-${i}`),
        }),
      )
      .join(""),
    detail: dot(pit.x, pit.y, 21, inks.detail, s("pit")),
    accent:
      dot(pit.x + 2.5, pit.y - 2, 22, inks.accent, s("pit-ink")) +
      sketch.circle(pit.x, pit.y, 46, {
        ...pen.accent,
        strokeWidth: 2.4,
        seed: s("halo"),
      }),
  }
}

// Small shapes spaced apart across a round field: rings, ticks, triangles, crosses and dots.
import { sketch } from "../rough"
import { stream } from "../seed"
import { dot, pens, seeds, turn, type Point } from "./pens"
import type { Motif } from "./types"

export const scatter: Motif = (seed, inks) => {
  const place = stream(seed, "scatter:place")
  const s = seeds(seed, "scatter")
  const pen = pens(inks)
  const spots: Point[] = []
  for (let tries = 0; tries < 240 && spots.length < 30; tries++) {
    const a = place.between(0, 6.28)
    const r = Math.sqrt(place.next()) * 108
    const p: Point = [120 + Math.cos(a) * r, 120 + Math.sin(a) * r]
    if (spots.every((q) => Math.hypot(q[0] - p[0], q[1] - p[1]) >= 27))
      spots.push(p)
  }

  const out = { line: "", detail: "", accent: "" }
  spots.forEach(([x, y], i) => {
    const kind = Math.floor(place.next() * 5)
    const angle = place.between(0, 6.28)
    const at = (dx: number, dy: number) => turn([x + dx, y + dy], [x, y], angle)
    const stroke = (a: Point, b: Point, label: string) =>
      sketch.line(a[0], a[1], b[0], b[1], {
        ...pen.accent,
        strokeWidth: 2.6,
        seed: s(label),
      })
    if (kind === 0)
      out.line += sketch.circle(x, y, place.between(13, 19), {
        ...pen.fine,
        seed: s(i),
      })
    else if (kind === 1)
      out.line += sketch.curve([at(-7, 0), at(-2, 6), at(8, -7)], {
        ...pen.fine,
        strokeWidth: 2.6,
        seed: s(i),
      })
    else if (kind === 2)
      out.accent += sketch.polygon([at(0, -9), at(8, 6), at(-8, 6)], {
        ...pen.accent,
        strokeWidth: 2.4,
        seed: s(i),
      })
    else if (kind === 3)
      out.accent +=
        stroke(at(-7, 0), at(7, 0), `${i}a`) +
        stroke(at(0, -7), at(0, 7), `${i}b`)
    else out.detail += dot(x, y, place.between(7, 11), inks.detail, s(i))
  })
  return out
}

// A branching stem with leaves on alternate sides, two of them inked, and berries at the tip.
import { sketch } from "../rough"
import { stream } from "../seed"
import { dot, pens, seeds, type Point } from "./pens"
import type { Motif } from "./types"

export const sprig: Motif = (seed, inks) => {
  const place = stream(seed, "sprig:place")
  const s = seeds(seed, "sprig")
  const pen = pens(inks)
  const base: Point = [place.between(100, 140), 230]
  const tip: Point = [base[0] + place.between(-45, 45), place.between(28, 48)]
  const bend: Point = [(base[0] + tip[0]) / 2 + place.between(-40, 40), 130]
  // Multiplication rather than **: engines may compute x ** 2 differently depending on how the code was optimised.
  const along = (t: number): Point => {
    const u = 1 - t
    return [
      u * u * base[0] + 2 * u * t * bend[0] + t * t * tip[0],
      u * u * base[1] + 2 * u * t * bend[1] + t * t * tip[1],
    ]
  }
  const stem = Array.from({ length: 9 }, (_, i) => along(i / 8))
  const inked = new Set([
    1 + Math.floor(place.next() * 2),
    3 + Math.floor(place.next() * 3),
  ])

  const leaves = [0.22, 0.34, 0.46, 0.58, 0.7, 0.82].map((t, i) => {
    const p = along(t)
    const q = along(t + 0.02)
    const side = i % 2 ? 1 : -1
    const heading =
      Math.atan2(q[1] - p[1], q[0] - p[0]) + side * place.between(0.85, 1.15)
    const length = place.between(44, 56) * (1 - t * 0.45)
    const end: Point = [
      p[0] + Math.cos(heading) * length,
      p[1] + Math.sin(heading) * length,
    ]
    const mid: Point = [(p[0] + end[0]) / 2, (p[1] + end[1]) / 2]
    const w = length * 0.36
    const normal: Point = [-Math.sin(heading) * w, Math.cos(heading) * w]
    const outline: Point[] = [
      p,
      [mid[0] + normal[0], mid[1] + normal[1]],
      end,
      [mid[0] - normal[0], mid[1] - normal[1]],
    ]
    if (!inked.has(i))
      return {
        line: sketch.loop(outline, { ...pen.fine, seed: s(`leaf-${i}`) }),
        accent: "",
      }
    const fill = {
      fill: inks.accent,
      fillStyle: "hachure" as const,
      hachureGap: 4.5,
      hachureAngle: (heading * 180) / Math.PI + 40,
    }
    return {
      line: "",
      accent: sketch.loop(outline, {
        ...pen.accent,
        strokeWidth: 2.4,
        ...fill,
        seed: s(`leaf-${i}`),
      }),
    }
  })

  return {
    line:
      sketch.curve(stem, { ...pen.fine, strokeWidth: 3, seed: s("stem") }) +
      leaves.map((l) => l.line).join(""),
    detail: [0, 1, 2]
      .map((k) =>
        dot(
          tip[0] + place.between(-12, 12),
          tip[1] + place.between(-12, 6),
          11,
          inks.detail,
          s(`berry-${k}`),
        ),
      )
      .join(""),
    accent: leaves.map((l) => l.accent).join(""),
  }
}

// Truchet tiles: a grid of cells, each with two quarter arcs in one of two turns, a few filled quarters in accent.
import { sketch } from "../rough"
import { stream } from "../seed"
import { seeds, type Point } from "./pens"
import type { Motif } from "./types"

const CELL = 48
const ORIGIN = 24

function quarter(cx: number, cy: number, r: number, from: number): Point[] {
  return Array.from({ length: 7 }, (_, i) => {
    const a = from + (i / 6) * (Math.PI / 2)
    return [cx + Math.cos(a) * r, cy + Math.sin(a) * r]
  })
}

export const tiles: Motif = (seed, inks) => {
  const place = stream(seed, "tiles:place")
  const s = seeds(seed, "tiles")
  const pen = { stroke: inks.line, strokeWidth: 4, roughness: 0.8 }
  const out = { line: "", accent: "", detail: "" }
  const r = CELL / 2

  for (let row = 0; row < 4; row++)
    for (let col = 0; col < 4; col++) {
      const x = ORIGIN + col * CELL
      const y = ORIGIN + row * CELL
      const flipped = place.next() > 0.5
      // Two arcs centred on opposite corners of the cell.
      const corners: [Point, number][] = flipped
        ? [
            [[x + CELL, y], Math.PI / 2],
            [[x, y + CELL], -Math.PI / 2],
          ]
        : [
            [[x, y], 0],
            [[x + CELL, y + CELL], Math.PI],
          ]
      corners.forEach(
        ([[cx, cy], from], k) =>
          (out.line += sketch.curve(quarter(cx, cy, r, from), {
            ...pen,
            seed: s(`${row}-${col}-${k}`),
          })),
      )
      const roll = place.next()
      if (roll > 0.82) {
        const [[cx, cy], from] = corners[0] as [Point, number]
        out.accent += sketch.polygon([[cx, cy], ...quarter(cx, cy, r, from)], {
          seed: s(`fill-${row}-${col}`),
          stroke: inks.accent,
          fill: inks.accent,
          fillStyle: "solid",
          strokeWidth: 1,
          roughness: 0.6,
        })
      } else if (roll < 0.1) {
        out.detail += sketch.circle(x + r, y + r, 9, {
          seed: s(`dot-${row}-${col}`),
          stroke: inks.detail,
          fill: inks.detail,
          fillStyle: "solid",
          strokeWidth: 1,
          roughness: 0.6,
        })
      }
    }
  return out
}

import type { PrintInks } from "../inks"

/** One print's strokes, split by drum so each drum can sit slightly out of register. */
export interface MotifDrawing {
  line: string
  detail: string
  accent: string
  /** Centre the accent drum turns around when the print animates. */
  pivot?: { x: number; y: number }
}

export interface MotifOptions {
  /** Text a motif may print, such as a monogram's initials. */
  text?: string
}

/** A motif draws inside a 240 × 240 area and may overflow it by up to 20 units on each side. */
export type Motif = (
  seed: number,
  inks: PrintInks,
  options: MotifOptions,
) => MotifDrawing

// Seeded 2D value noise for flow fields and wobbly contours: a lattice of random values, smoothly interpolated.
import { prng } from "./seed"

const SIZE = 16

export function valueNoise(seed: number, scale: number) {
  const next = prng(seed)
  const lattice = Array.from({ length: SIZE * SIZE }, () => next())
  const at = (x: number, y: number) =>
    lattice[
      (((y % SIZE) + SIZE) % SIZE) * SIZE + (((x % SIZE) + SIZE) % SIZE)
    ] ?? 0
  const smooth = (t: number) => t * t * (3 - 2 * t)
  /** Noise in [0, 1) at a point; `scale` is the lattice spacing in drawing units. */
  return (px: number, py: number) => {
    const x = px / scale
    const y = py / scale
    const x0 = Math.floor(x)
    const y0 = Math.floor(y)
    const tx = smooth(x - x0)
    const ty = smooth(y - y0)
    const top = at(x0, y0) + (at(x0 + 1, y0) - at(x0, y0)) * tx
    const bottom = at(x0, y0 + 1) + (at(x0 + 1, y0 + 1) - at(x0, y0 + 1)) * tx
    return top + (bottom - top) * ty
  }
}

// A print is a seeded riso illustration: drums of ink, each grained and slightly out of register, overprinted.
import { grainFilter } from "./filters"
import { CSS_INKS, type InkSet, type PrintInks } from "./inks"
import { motifs, type MotifName } from "./motifs"
import { seedOf, stream } from "./seed"

export interface PrintOptions {
  motif: MotifName
  seed: string | number
  /** A named ink set (re-inked by CSS), or plain colours for renders without a stylesheet. */
  inks?: InkSet | PrintInks
  /** Text the motif prints, such as a monogram's name. */
  text?: string
  /**
   * How far drums drift out of register. "css" scales a seeded direction by the --misregister custom property,
   * so the variation level controls it; a number bakes the offset in user units (for share images).
   */
  registration?: "css" | number
  /** Makes the print meaningful to assistive technology; without it the print is decorative. */
  title?: string
  /** A self-contained file: size and namespace on the root, overprinting inline. Pair with plain-colour inks. */
  standalone?: boolean
}

const DRUMS = ["line", "detail", "accent"] as const

const escape = (text: string) =>
  text.replace(/[&<>"]/g, (c) => `&#${c.charCodeAt(0)};`)

export function print({
  motif,
  seed,
  inks,
  text,
  registration = "css",
  title,
  standalone = false,
}: PrintOptions) {
  const n = typeof seed === "number" ? seed >>> 0 : seedOf(seed)
  const colours = typeof inks === "object" ? inks : CSS_INKS
  const drawing = motifs[motif](n, colours, {
    ...(text === undefined ? {} : { text }),
  })
  const drift = stream(n, "print:register")
  const id = `patina-print-${motif}-${n.toString(36)}`

  const filters = DRUMS.map((drum, i) =>
    grainFilter(`${id}-${drum}`, n + i * 3),
  ).join("")
  const groups = DRUMS.map((drum) => {
    const dx = drift.signed().toFixed(2)
    const dy = drift.signed().toFixed(2)
    const blend = standalone ? "mix-blend-mode:multiply" : ""
    const offset =
      registration === "css"
        ? ` style="translate:calc(var(--misregister, 1px) * ${dx}) calc(var(--misregister, 1px) * ${dy});${blend}"`
        : ` transform="translate(${(Number(dx) * registration).toFixed(2)} ${(Number(dy) * registration).toFixed(2)})"${blend ? ` style="${blend}"` : ""}`
    return `<g class="patina-drum" data-drum="${drum}" filter="url(#${id}-${drum})"${offset}>${drawing[drum]}</g>`
  }).join("")

  const set = typeof inks === "string" ? ` data-inks="${inks}"` : ""
  const label = title
    ? ` role="img" aria-label="${escape(title)}"`
    : ` aria-hidden="true"`
  const file = standalone
    ? ` xmlns="http://www.w3.org/2000/svg" width="560" height="560"`
    : ""
  const svg = `<svg${file} class="patina-print" data-motif="${motif}"${set} viewBox="-20 -20 280 280"${label}><defs>${filters}</defs>${groups}</svg>`
  return { svg, seed: n }
}

"use client"

import { useMemo, type ComponentProps } from "react"
import {
  print,
  type InkSet,
  type MotifName,
  type PrintInks,
} from "@/patina/ink"
import { cn } from "@/patina/lib/utils"
import { useSeed } from "./seed-scope"

export interface PrintProps extends Omit<
  ComponentProps<"span">,
  "children" | "title"
> {
  motif: MotifName
  /** Same seed, same print. Without one, the print takes its seed from the nearest SeedScope. */
  seed?: string | number
  inks?: InkSet | PrintInks
  /** Text the motif prints, such as a monogram's name. */
  text?: string
  /** Makes the print meaningful to assistive technology; without it the print is decorative. */
  title?: string
}

/** A seeded riso illustration. */
export function Print({
  motif,
  seed,
  inks,
  text,
  title,
  className,
  ...props
}: PrintProps) {
  const scoped = useSeed(`print:${motif}`)
  const resolved = seed ?? scoped
  const { svg } = useMemo(
    () => print({ motif, seed: resolved, inks, text, title }),
    [motif, resolved, inks, text, title],
  )
  return (
    <span
      data-slot="print"
      data-motif={motif}
      className={cn("block", className)}
      dangerouslySetInnerHTML={{ __html: svg }}
      {...props}
    />
  )
}
